/**
 * Re-points an issue at another project. Kept for the import tool's
 * "merge projects" step, which renumbers in a second pass; the row keeps its
 * number here so the pass can match it up again.
 */
export async function relocateIssue(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
): Promise<Issue> {
  const db = getDb();
  const row = db.transaction((tx) => {
    const current = tx.select().from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) return null;

    const counter = tx.select().from(projectIssueNumbers)
      .where(and(eq(projectIssueNumbers.orgId, orgId), eq(projectIssueNumbers.projectId, projectId)))
      .get();
    const observed = tx.select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)))
      .get();
    const nextNumber = Math.max(counter?.lastNumber ?? 0, observed?.value ?? 0) + 1;
    tx.insert(projectIssueNumbers)
      .values({ orgId, projectId, lastNumber: nextNumber })
      .onConflictDoUpdate({ target: projectIssueNumbers.projectId, set: { lastNumber: nextNumber } })
      .run();

    const updated = tx.update(issues)
      .set({ projectId, number: nextNumber, updatedAt: toIsoTimestamp(new Date()) })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();
    return { row: updated, number: nextNumber };
  }).immediate();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row.row);
}

